// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address initialOwner, address newOwner) public {
        vm.assume(initialOwner != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(initialOwner != newOwner);

        // initialize with initialOwner to set up ownership state
        c.initialize(1, 1, "test", initialOwner);

        // record the actual owner after initialization
        address actualOwner1 = c.owner();

        // transfer ownership to newOwner
        vm.prank(initialOwner);
        c.transferOwnership(newOwner);
        vm.prank(newOwner);
        c.acceptOwnership();

        address actualOwner2 = c.owner();

        // The reference must return the correct owner in both states.
        // The mutant returns address(0x1) constantly, so it will fail for at least one of these calls.
        assertTrue(actualOwner1 == initialOwner && actualOwner2 == newOwner);
    }
}

