pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != address(this));

        // initialize the contract
        address protocolFeeDest = address(0x1);
        c.initialize(1, 1, "test", protocolFeeDest);

        // start a two-step ownership transfer from the current owner to newOwner
        vm.prank(address(this));
        c.transferOwnership(newOwner);

        // newOwner accepts ownership
        vm.prank(newOwner);
        c.acceptOwnership();

        // the current owner must now be newOwner
        address currentOwner = c.owner();
        assertTrue(currentOwner == newOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address constant INITIAL_OWNER = address(0x123);

    function setUp() public {
        c = new C();
        // Initialize the contract (required to get out of the uninitialized state)
        // We use a minimal cred chain setup.
        vm.prank(address(this));
        c.initialize(1, 1, "test", address(this));
        // The contract must be owned by the caller of initialize (address(this))
    }

    function testFuzz_property(address newOwner) public {
        // The domain: newOwner must not be the zero address because Ownable prevents it.
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != address(this));

        // Record the owner before the transfer
        address ownerBefore = c.owner();

        // Transfer ownership to trigger the two-step process
        vm.prank(address(this));
        c.transferOwnership(newOwner);

        // Owner should not have changed yet (pending)
        address ownerAfterTransfer = c.owner();

        // Accept ownership from the new owner
        vm.prank(newOwner);
        c.acceptOwnership();

        // Finally, owner must be the newOwner
        address ownerAfterAccept = c.owner();

        // For ANY non-zero newOwner different from the current owner:
        // 1. Immediately after transferOwnership, owner() still returns the original owner.
        // 2. After acceptOwnership, owner() returns newOwner.
        // The buggy version reassigns the slot to the fixed OwnableStorageLocation inside owner(),
        // which means it will always read from that single slot, ignoring the actual struct binding.
        // Thus either ownerBefore will differ, or the final owner will not equal newOwner.
        assertTrue(
            ownerBefore == address(this) &&
            ownerAfterTransfer == address(this) &&
            ownerAfterAccept == newOwner
        );
    }
}

