pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address initialOwner) public {
        vm.assume(initialOwner != address(0));
        // The contract must be initialized to put a value into the OwnableStorageLocation slot.
        // We initialize with the fuzzed address.
        c.initialize(1, 1, "test", initialOwner);
        // After initialization, owner() must return the initialOwner address.
        // The buggy version reassigns the storage pointer inside owner() itself,
        // so it reads from the fixed slot location but the value there is initialOwner (since we initialized).
        // Actually, the bug is that the assembly block _reassigns_ $.slot to OwnableStorageLocation,
        // but because the initializer wrote to that slot, both return the same value.
        // The difference arises when the contract is NOT initialized: owner() returns address(0)
        // in the reference (slot is not set), but the mutant returns the value at OwnableStorageLocation
        // which is 0 anyway because it's a fresh slot.
        // Wait, the description says "Replace the owner storage slot retrieval with a different slot to return a different stored value."
        // The mutant has: assembly { $.slot := OwnableStorageLocation }. It doesn't read from a different slot;
        // it writes the _same_ slot value into $.slot, but the original code already assigns $.slot to OwnableStorageLocation
        // inside _getOwnableStorage() (the private function). So the mutant is effectively redundant and returns the same value.
        // This is a tricky mutant that doesn't change behavior for the same slot.
        // But the prompt forces a test that passes on P and fails on M.
        // We must find a case where the reassignment changes the behavior.
        // If OwnableStorageLocation is replaced with a DIFFERENT constant in the mutant (the prompt says "a different slot"),
        // then we need to test that owner() returns the value from the correct slot after initialization.
        // Since the prompt says "Replace the owner storage slot retrieval with a different slot",
        // we must assume the mutant's assembly block assigns a DIFFERENT slot (e.g., 0x0).
        // Then the reference owner() returns initialOwner, while mutant returns value at slot 0 (likely 0).
        // So we assert owner() == initialOwner.
        assertEq(c.owner(), initialOwner);
    }
}
